"use strict";

function run() {
  const finalized = new Set();
  const marker = {};
  const registry = new FinalizationRegistry(value => finalized.add(value));
  (function registerGarbage() {
    for (let i = 0; i < 3; i++) registry.register({ payload: new Array(1024).fill(i) }, i, marker);
  })();
  const started = Date.now();
  let garbage = [];
  const timer = setInterval(() => {
    // Also exercise the normal collection scheduler, including on macOS (without the Linux probe).
    garbage = Array.from({ length: 24 }, (_, i) => new Array(8192).fill(i));
    if (finalized.size === 3 || Date.now() - started > 10000) {
      clearInterval(timer);
      registry.unregister(marker); // Keep the registry alive until its callbacks have run.
      garbage = [];
      console.log(finalized.size === 3
        ? "ok JavaScriptCore finalization callbacks return through the host event loop"
        : "FAIL JavaScriptCore finalization callbacks did not run");
    }
  }, 20);
}

module.exports = { run };
